EXECUTESCRIPTPARA.INTERNALSCRIPTCODE:
# Define the category hierarchy (Main Categories & Subcategories)
poi_hierarchy = [
    {
        "no": 1,
        "code": "ADM",
        "name": "ADM",
        "subcategories": [
            {"no": 10, "code": "ADM0", "name": "ADM0"},
            {"no": 11, "code": "ADM1", "name": "ADM1"},
            {"no": 12, "code": "ADM2", "name": "ADM2"},
            {"no": 13, "code": "ADM3", "name": "ADM3"},
        ]
    },
    {
        "no": 2,
        "code": "POI",
        "name": "POI",
        "subcategories": [
            {"no": 20, "code": "All", "name": "All"},
            {"no": 21, "code": "Healthcare", "name": "Healthcare"},
            {"no": 22, "code": "Leisure", "name": "Leisure"},
            {"no": 23, "code": "Retail", "name": "Retail"},
            {"no": 24, "code": "Education", "name": "Education"},
            {"no": 25, "code": "Government", "name": "Government"},
        ]
    },
    {
        "no": 3,
        "code": "Flood",
        "name": "Flood",
        "subcategories": [
            {"no": 31, "code": "Flood Extent 1", "name": "Flood Extent 1"},
        ]
    },
    {
        "no": 4,
        "code": "Public Transport Lines",
        "name": "Public Transport Lines",
        "subcategories": [
            {"no": 41, "code": "PuT Lines 1", "name": "PuT Lines 1"},
        ]
    }
]

# Map currently existing POI categories in the network
existing_cats = {cat.AttValue("No"): cat for cat in Visum.Net.POICategories.GetAll}

# ------------------------------------------------------------------------------
# Create and Link POI Categories & Subcategories
# ------------------------------------------------------------------------------
for main_item in poi_hierarchy:
    main_no = main_item["no"]

    # 1. Main Category
    if main_no not in existing_cats:
        try:
            main_cat = Visum.Net.AddPOICategory()
            main_cat.SetAttValue("No", main_no)
            main_cat.SetAttValue("Code", main_item["code"])
            main_cat.SetAttValue("Name", main_item["name"])
            existing_cats[main_no] = main_cat
            print(f"Main category '{main_item['name']}' (ID: {main_no}) created.")
        except Exception as e:
            print(f"Error creating main category {main_no}: {e}")
    else:
        print(f"Main category '{main_item['name']}' (ID: {main_no}) already exists.")

    # 2. Subcategories
    for sub_item in main_item["subcategories"]:
        sub_no = sub_item["no"]
        if sub_no not in existing_cats:
            try:
                sub_cat = Visum.Net.AddPOICategory()
                sub_cat.SetAttValue("No", sub_no)
                sub_cat.SetAttValue("Code", sub_item["code"])
                sub_cat.SetAttValue("Name", sub_item["name"])
                sub_cat.SetAttValue("PARENTCATNO", main_no)
                existing_cats[sub_no] = sub_cat
                print(f"  --> Subcategory '{sub_item['name']}' (ID: {sub_no}) created under Parent {main_no}.")
            except Exception as e:
                print(f"Error creating subcategory {sub_no}: {e}")
        else:
            try:
                # Update parent category for already existing categories
                sub_cat = existing_cats[sub_no]
                sub_cat.SetAttValue("PARENTCATNO", main_no)
                print(f"  --> Subcategory '{sub_item['name']}' (ID: {sub_no}) updated with Parent {main_no}.")
            except Exception as e:
                print(f"Error updating subcategory {sub_no}: {e}")

print("POI category creation fully completed.")

target_link_types = [900, 901]
new_cap_prt = 200

for lt_no in target_link_types:
    try:
        link_type = Visum.Net.LinkTypes.ItemByKey(lt_no)
        link_type.SetAttValue("CapPrt", new_cap_prt)
        print(f"LinkType {lt_no}: CapPrt successfully updated to {new_cap_prt}.")
    except Exception as e:
        print(f"Could not update LinkType {lt_no}: {e}")

print("\nLink type update process finished.")

# Get a set of all currently existing demand segment codes in the network existing_dsegs = {ds.AttValue("CODE") for ds in Visum.Net.DemandSegments.GetAll}
# Mapping of Demand Segments to their corresponding RIN matrices (using underscores) dseg_matrices = { "CFL0": "RIN_CFL_0_n=2", "CFL1": "RIN_CFL_1_n=2", "CFL2": "RIN_CFL_2_n=2", "CFL3": "RIN_CFL_3_n=5", "CFL4": "RIN_CFL_4_n=5" }
target_ts_no = "0"
# Create demand segments only if they don't exist, and update their demand matrices for dseg_code, mat_code in dseg_matrices.items(): target_matrix = f'Matrix([CODE]="{mat_code}")'
# Only add if it doesn't already exist to avoid Visum internal error logging if dseg_code not in existing_dsegs: Visum.Net.AddDemandSegment(dseg_code, "CAR")
# Retrieve the demand segment and update its description/matrix attributes dseg_desc = Visum.Net.DemandSegments.ItemByKey(dseg_code).GetDemandDescription() dseg_desc.SetAttValue("DemandTimeSeriesNo", target_ts_no) dseg_desc.SetAttValue("Matrix", target_matrix)
# Mapping of procedure comment keywords to Demand Segment sets procedure_assignments = { "CFL 0/1 assignment": "CFL0,CFL1", "CFL 2 assignment": "CFL2", "CFL 3 assignment": "CFL3", "CFL 4 assignment": "CFL4" }
# Assign demand segments to assignment procedure operations based on comment matching for procedure in Visum.Procedures.Operations.GetAll: comment = procedure.AttValue("Comment") or "" for target_comment, dseg_set in procedure_assignments.items(): if target_comment in comment: procedure.PrTAssignmentParameters.SetAttValue("DSegSet", dseg_set) break

# Helper function to set impedance function term parameters def set_term(fcn_obj, term_idx, coeff1, attr1, op, coeff2, attr2): term = fcn_obj.ImpedanceFunctionTerm(term_idx) term.SetAttValue("FIRSTATTRCOEFF", str(coeff1)) term.SetAttValue("FIRSTATTRNAME", attr1) term.SetAttValue("OPERATION", op) term.SetAttValue("SECONDATTRCOEFF", str(coeff2)) term.SetAttValue("SECONDATTRNAME", attr2)
# Retrieve active mode from demand segment CFL0 mode = Visum.Net.DemandSegments.ItemByKey("CFL0").AttValue("Mode\\TSysSet") imp_fcns = Visum.Procedures.Functions.ImpedanceFunctions(mode)
# 1. Configure Link Impedance Terms link_fcn = imp_fcns.ImpedanceFunction("LINK") link_terms = [ (1, 100, "T0_PRTSYS(CAR)", "MULTIPLY", 1, "RIN_IMPFAC"), (2, 0, "T0_PRTSYS(CAR)", "NONE", 0, "1.0"), (3, 0, "T0_PRTSYS(CAR)", "MULTIPLY", 0.02, "LENGTH"), (4, 0, "T0_PRTSYS(CAR)", "MULTIPLY", 0.05, "LENGTH"), (5, 0, "T0_PRTSYS(CAR)", "MULTIPLY", 0.2, "RIN_CFL"), (6, 0, "T0_PRTSYS(CAR)", "MULTIPLY", 0.4, "RIN_CFL") ]
for term_idx, c1, a1, op, c2, a2 in link_terms: set_term(link_fcn, term_idx, c1, a1, op, c2, a2)
# 2. Configure Connector, Turn, and Main Turn Impedance Terms other_terms = [ ("CONNECTOR", 1, 100, "T0_TSYS(CAR)", "MULTIPLY", 1, "1.0"), ("TURN", 1, 100, "T0_PRTSYS(CAR)", "MULTIPLY", 1, "1.0"), ("MAINTURN", 1, 0, "T0_PRTSYS(CAR)", "MULTIPLY", 0, "1.0") ]
for fcn_type, term_idx, c1, a1, op, c2, a2 in other_terms: set_term(imp_fcns.ImpedanceFunction(fcn_type), term_idx, c1, a1, op, c2, a2)

def create_and_activate_study_area(Visum, terr_no=10, terr_name="StudyArea"): # Safely check existing territory numbers without triggering COM lookup errors existing_terr_nos = {t.AttValue("NO") for t in Visum.Net.Territories.GetAll}
if terr_no in existing_terr_nos: print(f"Territory {terr_no} already exists. Skipping creation.") else: try: # Step 1: Filter zones for Study Area (ZONETYPE in PA, IA1, IA2) zf = Visum.Filters.ZoneFilter() zf.Init() zf.AddCondition("OP_NONE", False, "ZONETYPE", "EqualVal", "PA") zf.AddCondition("OP_OR", False, "ZONETYPE", "EqualVal", "IA1") zf.AddCondition("OP_OR", False, "ZONETYPE", "EqualVal", "IA2")
num_filtered_zones = Visum.Net.Zones.CountActive if num_filtered_zones > 0: # Step 2: Convert filtered zones into temporary territories Visum.Net.Zones.ConvertInto( TargetNetObjName="Territory", TargetCategory=None, SourceForKeyAttID="NO", DoNothingInCaseOfConflict=True, AllocateObjectsWithinPolygon=False, OnlyActive=True )
# Step 3: Filter temporary RC_* territories and aggregate surfaces tf = Visum.Filters.TerritoryFilter() tf.Init() tf.AddCondition("OP_NONE", False, "NAME", "EqualVal", "RC_*")
num_new_territories = Visum.Net.Territories.CountActive if num_new_territories > 0: Visum.Net.Territories.AggregateSurfaces(OnlyActive=True)
# Reset filters immediately after aggregation zf.Init() tf.Init()
# Step 4: Rename and renumber aggregated territory (highest ID) highest_no = int(Visum.Net.AttValue(r"MAX:TERRITORIES\NO")) final_territory = Visum.Net.Territories.ItemByKey(highest_no) final_territory.SetAttValue("NAME", terr_name)
try: final_territory.SetAttValue("NO", terr_no) print(f"Territory {terr_no} ('{terr_name}') successfully created.") except Exception as renum_err: print(f"Renumbering to {terr_no} failed: {renum_err}. Keeping ID {highest_no}.")
else: print("No matching zones found for study area territory.") zf.Init()
except Exception as e: print(f"Error creating territory: {e}")
# Step 5: Activate Territory 10 try: Visum.Net.SetTerritoryActive(terr_no) print(f"Territory {terr_no} successfully activated.") except Exception: print(f"Territory {terr_no} is active.")
# Execute Territory setup create_and_activate_study_area(Visum)

